components.css:
.ds-messenger {
  --pc-color: #6a58e0; --pc-color-end: #9a4fd3; --pc-light: #b9afff;
  --pc-bg: color-mix(in srgb, var(--pc-color) 5%, #fff); --pc-input: #fff;
  --pc-ink: #2a2b47; --pc-muted: #636786; --pc-error: #b8203f;
  --pc-accent: color-mix(in srgb, var(--pc-color) 80%, #17172e);
  --pc-soft: color-mix(in srgb, var(--pc-color) 11%, #fff);
  --pc-line: color-mix(in srgb, var(--pc-color) 18%, #e9e9f0);
  --pc-line-strong: color-mix(in srgb, var(--pc-color) 35%, #9a9cb5);
  --pc-round: ui-rounded, 'Hiragino Maru Gothic ProN', 'Yuanti SC', system-ui, sans-serif;

  background: var(--pc-bg); color: var(--pc-ink); border-radius: 22px;
  font: 400 14px/1.6 system-ui, -apple-system, 'PingFang SC', 'Microsoft YaHei', sans-serif;
  isolation: isolate; text-align: left; color-scheme: light; pointer-events: auto;
  font-variant-numeric: tabular-nums;
}

.ds-primary { display: inline-flex; justify-content: center; align-items: center; gap: 8px; width: 100%; padding: 12px 16px; min-height: 44px; border: 0; border-radius: 24px; color: #fff !important; background: var(--pc-color); font-weight: 650 !important; transition: background-color .15s; }

.ds-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--pc-color) 85%, #17172e); }

.ds-primary svg { width: 17px; height: 17px; }

.ds-manage-page form > .ds-primary, .ds-manage-page form > .ds-small { margin-top: 2px; }
.ds-messenger button,.ds-messenger input{font:inherit}.ds-messenger :focus-visible{outline:2px solid var(--pc-accent);outline-offset:3px}

