.ds-small { border: 1px solid var(--pc-line-strong); background: var(--pc-input); color: var(--pc-accent) !important; min-height: 36px; padding: 7px 14px; border-radius: 20px; font-size: 12px !important; font-weight: 600 !important; transition: background-color .15s, border-color .15s; }

.ds-small:hover:not(:disabled), .ds-key button:hover:not(:disabled) { background: var(--pc-soft); border-color: var(--pc-accent); }

