.ds-field > span { display: block; margin-bottom: 6px; }

.ds-input { width: 100%; min-height: 42px; padding: 10px 12px; background: var(--pc-input); color: var(--pc-ink); border: 1px solid var(--pc-line-strong); border-radius: 10px; caret-color: var(--pc-accent); font-size: 13px !important; transition: border-color .15s; }

.ds-messenger .ds-input, .ds-messenger .ds-key button { font-weight: 400; }

.ds-input:hover:not(:disabled) { border-color: var(--pc-accent); }

.ds-input:focus-visible { border-color: var(--pc-accent); outline-offset: 2px; }

.ds-input::placeholder { color: var(--pc-muted); opacity: 1; }

textarea.ds-input { line-height: 1.65; }

.ds-mobile .ds-input, .ds-mobile .ds-compose-row textarea { font-size: 16px !important; }

