.ds-tabs { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: thin; scrollbar-color: var(--pc-line-strong) transparent; margin: 12px -6px 24px; padding: 4px 2px; }

.ds-tabs button { flex: 1 0 auto; border: 0; border-radius: 22px; background: transparent; min-height: 38px; padding: 8px 10px; font-size: 12px; color: var(--pc-muted) !important; white-space: nowrap; transition: color .15s, background-color .15s; }

.ds-tabs button:hover { background: var(--pc-soft); color: var(--pc-accent) !important; }

.ds-tabs button[aria-pressed='true'] { background: var(--pc-color); color: #fff !important; font-weight: 650; }

.ds-tabs button:focus-visible { outline-offset: -3px; }

.ds-mobile .ds-tabs button { min-height: 44px; }
