.ds-header::before { content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none; background: radial-gradient(circle, rgb(255 255 255 / .18) 1px, transparent 1.5px) right top / 7px 7px; mask-image: linear-gradient(105deg, transparent 35%, #000); }

.ds-header::after { content: ''; position: absolute; width: 90px; height: 180px; right: 16px; top: -60px; transform: rotate(32deg); border-inline: 1px solid rgb(255 255 255 / .15); z-index: -1; pointer-events: none; }

.ds-status { width: fit-content; max-width: 100%; padding: 3px 8px; border-radius: 20px; background: rgb(0 0 0 / .18); color: #fff; font-size: 10px; line-height: 1.5; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
