.ds-record-list { margin-top: 4px; border-top: 1px solid var(--pc-line); }

.ds-record { padding: 13px 0 6px; border-bottom: 1px solid var(--pc-line); overflow-wrap: anywhere; }

.ds-record p { margin: 0 0 6px; white-space: pre-wrap; line-height: 1.7; }

.ds-record[data-entry-id] > p { color: var(--pc-ink); }

.ds-record[data-memory-id] { position: relative; padding-left: 24px; }

.ds-record[data-memory-id]::before { content: ''; position: absolute; left: 0; top: 20px; width: 12px; height: 12px; background: var(--pc-accent); clip-path: polygon(50% 0, 63% 37%, 100% 50%, 63% 63%, 50% 100%, 37% 63%, 0 50%, 37% 37%); }

.ds-record[data-memory-id] > p:first-child + .ds-note { margin-top: 6px; }

.ds-record .ds-note { margin: 0 0 4px; font-size: 11px; }

.ds-record .ds-row-actions { margin: 4px 0; }

.ds-record .ds-link:not(.ds-danger) { color: var(--pc-ink) !important; }

.ds-record details { margin: 8px 0; font-size: 12px; }

.ds-record summary { cursor: pointer; color: var(--pc-muted); width: fit-content; }

.ds-record summary:hover { color: var(--pc-ink); }

.ds-record details p { margin: 6px 0; padding-left: 10px; border-left: 1px solid var(--pc-line-strong); color: var(--pc-muted); }

.ds-record form .ds-field { margin-bottom: 6px; }
